import {bindInstallUI} from './install.js';
import {enterView,celebrateAt,feedbackMotion} from './motion.js';
import {units,lessons,allPhrases,reference,sources} from './curriculum.js';
import {alphabet,vowels} from './alphabet.js';
import {emptyProgress,sanitize,mergeProgress,normalize,award,scheduleCard,streak,totalXP,dayKey,variant,makeSession,nextLesson,shuffled,answerMatches} from './engine.js';
import {mountTrace} from './trace.js';
import {writingCourseHTML,launchWritingRound} from './writing-course.js';
import {reconcileFreezes,sparkBalance,freezeStock,buyFreeze,dailyQuests,claimQuest,levelState,achievements,recordLesson,recordLetter,FREEZE_COST,FREEZE_CAP} from './game.js';
import {cloudConfigured,initCloud,signInGoogle,signOutGoogle,readCloud,writeCloud,deleteCloud,rewardSyncStatus} from './cloud.js';
const $=s=>document.querySelector(s), app=$('#app');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({book:'<path d="M3 5c3-1 6-1 9 1 3-2 6-2 9-1v14c-3-1-6-1-9 1-3-2-6-2-9-1zM12 6v14"/>',pen:'<path d="m4 16 12-12 4 4L8 20H4zM14 6l4 4"/>',repeat:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',library:'<path d="M4 4v16M9 4v16M14 4v16m4-15 3 14"/>',person:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 4 2 2v4l4 2 3-1 3 1 4-3v-3l2-3-2-4-3-1-1-3z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6z"/>',cup:'<path d="M4 8h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4zM17 9h2a3 3 0 0 1 0 6h-2M7 3v2m4-2v2"/>',bag:'<path d="M4 7h16l1 14H3zM8 7V5a4 4 0 0 1 8 0v2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',flag:'<path d="M5 22V3c5-4 9 4 14 0v11c-5 4-9-4-14 0"/>',flame:'<path d="M12 2c2 5-3 7-1 10 2 0 3-2 3-4 6 5 6 14-2 14C2 22 3 12 6 9c0 5 3 5 3 5-3-5 0-8 3-12z"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',heart:'<path d="M20 5c-3-3-6 0-8 2-2-2-5-5-8-2-5 5 4 12 8 16 4-4 13-11 8-16z"/>',google:'<path d="M21 12h-9m0-9a9 9 0 1 0 8 5"/>'})[name]||''}</svg>`;
let storageWarning=false;
function load(key){try{const next=reconcileFreezes(sanitize(JSON.parse(localStorage.getItem(key))));localStorage.setItem(key,JSON.stringify(next));return next;}catch{return reconcileFreezes(emptyProgress());}}
let user=null, key='binah:guest', progress=load(key), tab='learn', session=null, traceIndex=0, trace=null, wordQuery='',letterMode='course',syncTimer=null,syncState='local',pendingGuest=null,authReady=false,typingQuery='',typingFilter='all',typingSelected=new Set();
let activeUnit=units.findIndex(u=>u.id===nextLesson(lessons,progress).unit);
const bareSpell=text=>text.replace(/[\u0591-\u05C7]/g,'').replace(/השרותים/g,'השירותים').replace(/סכר/g,'סוכר').replace(/במזמן/g,'במזומן');
const he=text=>`<bdi lang="he" dir="rtl">${escape(progress.vowels?text:bareSpell(text))}</bdi>`;
const hePhrase=p=>he(progress.vowels?p.he:p.unpointed||bareSpell(p.he));
const displayWord=(word,p)=>{if(progress.vowels)return word;const from=p.he.split(' '),to=p.unpointed?.split(' '),i=from.indexOf(word);return to?.length===from.length&&i>=0?to[i]:bareSpell(word);};
const roman=p=>progress.transliteration?`<span class="roman">${escape(p.roman)}</span>`:'';
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4300);}
function save({cloud=true}={}){if(cloud)progress.updatedAt=Date.now();try{localStorage.setItem(key,JSON.stringify(progress));}catch{if(!storageWarning){storageWarning=true;toast('This browser cannot save progress. Export a backup in Settings.');}}if(user&&cloud){syncState='pending';clearTimeout(syncTimer);const uid=user.uid;syncTimer=setTimeout(()=>sync(uid),1800);}}
async function sync(uid){if(user?.uid!==uid)return;const snapshot=structuredClone(progress);syncState='saving';try{const merged=await writeCloud(uid,snapshot);if(user?.uid===uid){progress=mergeProgress(progress,merged);save({cloud:false});syncState='saved';}}catch{if(user?.uid===uid){syncState='error';toast('Cloud sync paused. Progress is saved on this device; retry in Settings.');}}if(tab==='settings'&&!session)render();}
function setTab(value){if(session){if(!confirm('Leave this lesson? Your completed lessons are saved, but this attempt will restart.'))return;session=null;}tab=value;location.hash=value;render();window.scrollTo({top:0,behavior:'instant'});}
const dueCards=()=>allPhrases.filter(p=>progress.cards[p.id]&&progress.cards[p.id].due<=Date.now());
function shell(content){const xp=totalXP(progress),today=progress.activity[dayKey()]||0;return `<aside class="sidebar"><a href="#learn" class="brand" aria-label="Binah home"><img class="brand-symbol" src="/logo-hebrew.svg" alt="בִּינָה" width="84" height="34"><strong class="brand-word">Binah</strong><small class="brand-tagline">HEBREW FOR REAL LIFE</small></a><nav aria-label="Main navigation">${[['learn','book','Learn'],['letters','pen','Letters'],['review','repeat','Practice'],['library','library','Field notes']].map(([id,i,title])=>`<button data-tab="${id}" class="nav-item ${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${icon(i)}<span>${title}</span>${id==='review'&&dueCards().length?`<span class="nav-count">${dueCards().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="small-promise"><span class="little-star">${icon('spark')}</span><p>A little Hebrew.<br>A little more connection.</p></div><button class="nav-item ${tab==='settings'?'active':''}" data-tab="settings">${icon(settingsIcon())}<span>${user?'Your account':'Your space'}</span><span class="avatar">${escape((progress.name||user?.displayName||'G')[0].toUpperCase())}</span></button></div></aside><div class="workspace"><header class="topbar"><button class="mobile-brand" data-tab="learn" aria-label="Binah home"><img src="/brand-mark.svg" width="30" height="30" alt=""><span>Binah</span></button><div class="breadcrumb">Your Hebrew journey <span>/</span> ${ {learn:'Learning path',letters:'The alef-bet',review:'Practice',library:'Field notes',settings:'Your space',rewards:'Your rewards'}[tab]}</div><div class="top-stats"><button class="streak-stat" data-tab="rewards" aria-label="Your streak and rewards">${icon('flame')} <strong>${streak(progress)}</strong><span class="stat-label">day streak</span></button><span title="Experience points">${icon('spark')} <strong>${xp}</strong><span class="stat-label">XP</span></span><button data-tab="settings" class="profile-dot" aria-label="Open your space">${escape((progress.name||'G')[0].toUpperCase())}</button></div></header><main id="main" class="page-main" tabindex="-1">${content}</main><footer class="footer"><span>בִּינָה <span aria-hidden="true">·</span> Understanding, one day at a time.</span><span>Made for real conversations.</span></footer></div>`;}
function settingsIcon(){return user?'person':'settings';}
function heading(kicker,title,description){return `<div class="page-heading"><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${description}</p></div>`;}
function learning(){const next=nextLesson(lessons,progress),unit=units[activeUnit],list=lessons.filter(l=>l.unit===unit.id),done=list.filter(l=>progress.completed[l.id]).length,today=progress.activity[dayKey()]||0;const completedCount=Object.keys(progress.completed).filter(id=>lessons.some(l=>l.id===id)).length;
return `${heading('YOUR NEXT LITTLE ADVENTURE',progress.name?`Shalom, ${escape(progress.name)}.`:'Let’s learn Hebrew.','Start with the words that open doors. Go at your own pace.')}<div class="daily-mini"><span>Today <strong>${Math.min(today,progress.goal)} / ${progress.goal} XP</strong></span><progress value="${Math.min(today,progress.goal)}" max="${progress.goal}" aria-label="Today’s learning intention"></progress><button class="text-button" data-tab="rewards">Daily quests</button></div><div class="learn-layout"><section class="path-column"><article class="continue-card"><div class="continue-copy"><span class="pill light">${completedCount?'KEEP YOUR MOMENTUM':'LET’S START TALKING'}</span><h2>${completedCount?escape(next.title):'Your first “shalom.”'}</h2><p><span class="hero-description-wide">${completedCount?'A few minutes today. A little more confidence tomorrow.':'Say hello, introduce yourself, and make your first connection.'}</span><span class="hero-description-compact">${completedCount?'Your next real-life conversation.':'Say hello. Start a conversation.'}</span></p><button class="button primary cream" data-lesson="${next.id}">${completedCount?'Continue learning':'Start learning'} ${icon('arrow')}</button><button class="hero-meta journey-rewards" data-tab="rewards">Level ${levelState(progress).level} <span>·</span> ${sparkBalance(progress)} sparks <span>·</span> ${freezeStock(progress)} freeze${freezeStock(progress)===1?'':'s'}</button></div><div class="hero-art" aria-hidden="true"><div class="art-sun">${icon('sun')}</div><div class="he-card one" lang="he">שָׁלוֹם<span>sha-LOM</span></div><div class="he-card two">א<span>ALEF</span></div><span class="art-dot"></span></div></article><div class="path-title"><div><p class="eyebrow">THE LEARNING PATH</p><h2>Small steps. Useful words.</h2></div><span class="muted">${completedCount} / ${lessons.length} lessons</span></div><label class="unit-select-label" for="unit-select">YOUR LEARNING PATH<select id="unit-select" aria-label="Choose a course unit">${units.map((u,i)=>`<option value="${i}" ${i===activeUnit?'selected':''}>Unit ${i+1} · ${u.title}</option>`).join('')}</select></label><div class="unit-picker" aria-label="Course units">${units.map((u,i)=>`<button class="${i===activeUnit?'selected':''}" data-unit="${i}" aria-label="Unit ${i+1}: ${u.title}" ${i===activeUnit?'aria-current="true"':''}>${String(i+1).padStart(2,'0')}</button>`).join('')}</div><article class="unit-banner ${unit.color}"><span class="unit-icon">${icon(unit.icon)}</span><div><p class="eyebrow">UNIT ${activeUnit+1} · ${activeUnit<8?'FOUNDATIONS':'EVERYDAY CONFIDENCE'}</p><h2>${unit.title}</h2><p>${unit.description}</p></div><span class="unit-he" lang="he" dir="rtl">${unit.he}</span></article><div class="lesson-list">${list.map((l,i)=>{const completed=!!progress.completed[l.id],available=l.index===0||!!progress.completed[lessons[l.index-1].id]||completed;return `<button class="lesson-row ${completed?'done':available?'current':'locked'}" data-lesson="${l.id}" ${available?'':`disabled`}><span class="lesson-node">${icon(completed?'check':available?'book':'lock')}</span><span class="lesson-info"><span class="eyebrow">LESSON ${i+1}</span><strong>${l.title}</strong><small>${completed?'Ready for a refresher':available?'Your next step':'Complete the previous lesson'}</small></span><span class="lesson-xp">${completed?'Completed':'+30 XP'}</span>${icon('arrow')}</button>`;}).join('')}</div><div class="unit-bottom"><span>${done} of ${list.length} complete</span><progress value="${done}" max="${list.length}" aria-label="Unit progress"></progress>${activeUnit<units.length-1?`<button class="text-button" data-unit="${activeUnit+1}">Explore next unit ${icon('arrow')}</button>`:''}</div></section><aside class="right-rail"><article class="daily-card"><div class="card-heading"><h3>Your daily intention</h3>${icon('sun')}</div><div class="goal-ring" style="--pct:${Math.min(today/progress.goal,1)*100}%"><svg viewBox="0 0 120 120" aria-hidden="true"><circle class="ring-track" cx="60" cy="60" r="51"/><circle class="ring-fill" cx="60" cy="60" r="51" stroke-dasharray="${Math.min(today/progress.goal,1)*320.45} 320.45"/></svg><div><strong>${Math.min(today,progress.goal)}<span> / ${progress.goal}</span></strong><small>XP TODAY</small></div></div><p>${today>=progress.goal?'Your intention, fulfilled. Nicely done.':'A few minutes is a lovely place to start.'}</p><button class="text-button" data-tab="rewards">Your quests & rewards</button></article><article class="letter-promo"><div class="promo-letter" lang="he">א</div><span class="eyebrow">MEET THE ALEF-BET</span><h3>It starts with a letter.</h3><p>Get to know the shapes, names, and sounds of Hebrew.</p><button class="text-button" data-tab="letters">Explore letters ${icon('arrow')}</button></article><article class="word-card"><span class="eyebrow">A WORD TO TAKE WITH YOU</span><p class="word-he" lang="he" dir="rtl">תּוֹדָה</p><p>to-DA <span>·</span> Thank you</p><button class="icon-button" data-speak="תּוֹדָה" aria-label="Hear toda">${icon('sound')}</button></article><p class="local-note">${icon(user?'check':'lock')}${user?'Your progress, across your devices.':'Your progress stays on this device.'}</p></aside></div>`;}
function lettersPage(){
 const l=alphabet[traceIndex],compact=matchMedia('(max-width: 767px)').matches;
 return `${heading('THE ALEF-BET','Your letter studio.','Practice a shape, hear its name, and make it yours.')}
 <div class="segment" role="group" aria-label="Alphabet views"><button data-letter-mode="course" class="${letterMode==='course'?'selected':''}">Lessons</button><button data-letter-mode="letters" class="${letterMode==='letters'?'selected':''}">Free practice</button><button data-letter-mode="vowels" class="${letterMode==='vowels'?'selected':''}">Vowels</button></div>
 ${letterMode==='course'?writingCourseHTML(progress):letterMode==='vowels'?`<div class="info-banner vowel-explainer">Vowel marks guide pronunciation. Alef carries the vowel in these examples. Everyday writing usually leaves the marks out.</div><div class="vowel-grid">${vowels.map(([h,n,sound])=>`<article class="vowel-card"><span lang="he" dir="rtl">${h}</span><h3>${n}</h3><p>${sound}</p></article>`).join('')}</div>`:`
 <div class="letters-layout">
 <section class="letter-library-section">
 <details class="letter-library" ${compact?'':'open'}><summary><span>Browse all 27 forms</span><small>${progress.traced.length} practiced</small>${icon('book')}</summary>
 <div class="alphabet-grid" dir="rtl">${alphabet.map((x,i)=>`<button data-letter="${i}" class="letter-tile ${i===traceIndex?'selected':''} ${progress.traced.includes(x.char)?'traced':''}" aria-label="Practice ${x.name}" aria-pressed="${i===traceIndex}"><span lang="he">${x.char}</span><small dir="ltr">${x.name.split(' /')[0]}</small>${progress.traced.includes(x.char)?'<span class="tiny-check" aria-label="Practiced">✓</span>':''}</button>`).join('')}</div></details>
 <details class="letter-facts-details"><summary><span class="letter-display" lang="he">${l.char}</span><span><strong>${l.name}</strong><span class="letter-sound">${l.sound}</span></span><span>About this letter +</span></summary><p>${l.note}</p><p class="muted">Read Hebrew right to left. The five final forms appear at the ends of words.</p><button class="text-button" data-speak="${l.he}">${icon('sound')} Hear the name</button></details>
 <button class="button secondary full" id="letter-quiz">Practice letter names ${icon('arrow')}</button>
 </section>
 <article class="trace-panel" data-feedback="idle">
 <div class="trace-letter-heading"><span class="trace-letter-glyph" lang="he" aria-hidden="true">${l.char}</span><div class="letter-select-wrap"><label for="letter-select">CHOOSE A LETTER</label><select id="letter-select">${alphabet.map((x,i)=>`<option value="${i}" ${i===traceIndex?'selected':''}>${x.char} · ${x.name}</option>`).join('')}</select></div><div class="trace-letter-sound"><span>LETTER SOUND</span><strong>${escape(l.sound)}</strong></div><button class="icon-button" data-speak="${l.he}" aria-label="Hear ${l.name}">${icon('sound')}</button></div>
 <div class="trace-practice-modes" role="group" aria-label="Writing assistance"><button data-trace-mode="guided" aria-pressed="true">Guided</button><button data-trace-mode="recall" aria-pressed="false">From memory</button></div><p class="trace-hint" id="trace-instruction" role="status" aria-atomic="true">Start at 1. Lift your finger after each stroke.</p>
 <div class="trace-stage"><div id="trace-writer" role="img" aria-label="Writing surface for ${l.name}. Draw with a finger, pen, or mouse. For keyboard practice, use Practice letter names instead." aria-describedby="trace-instruction"></div><div class="trace-stage-label" aria-hidden="true">${l.name}</div></div>
 <div class="trace-live"><span id="trace-count" aria-live="off">0 strokes</span><span id="trace-percent">0%</span></div><progress id="trace-progress" value="0" max="100" aria-label="Accepted writing strokes"></progress>
 <div class="trace-tools"><button class="text-button" id="trace-watch">${icon('repeat')} Watch</button><button class="text-button" id="trace-hint">Hint</button><button class="text-button" id="trace-clear">Restart</button></div>
 <button class="button primary full" id="trace-next" hidden>Next letter ${icon('arrow')}</button>
 <div class="trace-nav"><button class="text-button" data-letter="${(traceIndex+26)%27}">← Previous</button><span>${traceIndex+1} / 27</span><button class="text-button" data-letter="${(traceIndex+1)%27}">Next →</button></div>
 <details class="trace-guide-note"><summary>About these guides</summary><p>Print letters for reading signs, books, and screens. These guides teach one consistent way to form them; teachers and handwriting styles vary. For everyday handwriting, Hebrew also has cursive forms. Built with <a href="https://github.com/chanind/hanzi-writer" target="_blank" rel="noopener">Hanzi Writer</a> (MIT) and Noto Sans Hebrew (OFL).</p></details>
 </article></div>`}`;
}

function practicePage(){const due=dueCards(),learned=allPhrases.filter(p=>progress.cards[p.id]);return `${heading('MAKE IT STICK','Keep your Hebrew close.','Revisit what you’ve learned, without losing hearts or running out of chances.')}<div class="practice-grid"><article class="practice-card featured"><span class="practice-icon">${icon('repeat')}</span><span class="eyebrow">SPACED PRACTICE</span><h2>${due.length?due.length+' phrases ready to revisit.':'You’re right on time.'}</h2><p>${learned.length?(due.length?'Give familiar words another moment in the spotlight.':'Nothing due right now. You can still refresh your phrases.'):'Complete your first lesson to start a personal review collection.'}</p><button class="button primary" id="start-review" ${learned.length?'':'disabled'}>${due.length?'Review now':'Refresh learned phrases'} ${icon('arrow')}</button></article><article class="practice-card"><span class="practice-icon lavender">${icon('pen')}</span><span class="eyebrow">LETTER RECALL</span><h2>Alef, bet… and beyond.</h2><p>Match a letter to its name. A quick way to grow comfortable with a new alphabet.</p><button class="button secondary" id="letter-quiz">Practice letters ${icon('arrow')}</button></article><article class="practice-card typing-practice-card"><span class="practice-icon">${icon('book')}</span><span class="eyebrow">HEBREW TYPING</span><h2>Write it from memory.</h2><p>Translate useful phrases into Hebrew with the same typing exercise used in lessons, whenever you want.</p><div class="typing-entry-actions"><button class="button primary" id="start-typing">Random practice ${icon('repeat')}</button><button class="button secondary" id="choose-typing">Choose words & phrases ${icon('arrow')}</button></div></article></div><section class="typing-browser" id="typing-browser" hidden><div class="typing-browser-heading"><div><span class="eyebrow">MAKE IT YOURS</span><h2>What would you like to practise?</h2><p>Browse the course vocabulary and build a short typing round.</p></div><button class="icon-button" id="close-typing-browser" aria-label="Close phrase browser">${icon('close')}</button></div><label class="search-field">${icon('library')}<input id="typing-browse-search" type="search" placeholder="Search Hebrew, English or pronunciation…" value="${escape(typingQuery)}" aria-label="Search words and phrases"></label><div class="typing-filter-row"><button class="typing-filter active" data-typing-filter="all">All</button><button class="typing-filter" data-typing-filter="words">Words</button><button class="typing-filter" data-typing-filter="phrases">Phrases</button></div><div class="typing-selection-status"><span id="typing-selection-count">0 of 8 selected</span><span>Choose up to 8</span></div><div class="typing-choice-grid" id="typing-choice-grid"></div><button class="button primary full" id="start-selected-typing" disabled>Start selected practice ${icon('arrow')}</button></section><div class="collection-heading"><h2>Your phrase collection</h2><span class="muted">${learned.length} learned phrases</span></div><label class="search-field">${icon('library')}<input id="phrase-search" type="search" placeholder="Find a phrase in Hebrew or English…" value="${escape(wordQuery)}" aria-label="Search learned phrases"></label><div id="phrase-results">${phraseResults(learned)}</div>`;}
function phraseResults(learned){const q=normalize(wordQuery),filtered=learned.filter(p=>[p.he,p.en,p.roman,p.f?.he||''].some(s=>normalize(s).includes(q)));return filtered.length?`<div class="phrase-grid">${filtered.map(p=>{p=variant(p,progress.form);return `<article class="phrase-card"><button class="icon-button" data-speak="${escape(p.he)}" aria-label="Hear ${escape(p.en)}">${icon('sound')}</button><p class="hebrew">${hePhrase(p)}</p>${roman(p)}<p>${escape(p.en)}</p></article>`;}).join('')}</div>`:`<div class="empty-state">${icon('book')}<h3>${learned.length?'No matching phrases yet.':'Your words will find a home here.'}</h3><p>${learned.length?'Try another search.':'Finish a lesson, then come back to keep your new phrases close.'}</p><button class="text-button" data-tab="learn">Go to your path ${icon('arrow')}</button></div>`;}
function libraryPage(){return `${heading('A LITTLE UNDERSTANDING','Field notes for your journey.','The patterns behind the phrases. Come back whenever you’re curious.')}<div class="reference-grid">${reference.map((r,i)=>`<details class="reference-card" ${i===0&&!matchMedia('(max-width: 767px)').matches?'open':''}><summary><span class="reference-no">${String(i+1).padStart(2,'0')}</span><span><strong>${r.title}</strong><span lang="he" dir="rtl">${r.he}</span></span><span class="plus">+</span></summary><p>${r.body}</p></details>`).join('')}</div><article class="source-panel"><p class="eyebrow">ROOTED IN RESEARCH</p><h2>Good learning begins with good sources.</h2><p>These references inform the course scope, pronunciation, spelling, and language notes. Our activities and explanations are original. This is an introductory Modern Hebrew course; native-speaker editorial and audio review remain part of the roadmap.</p><div class="source-links">${sources.map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`).join('')}</div></article>`;}
function settingsPage(){return `${heading('YOUR SPACE','Make yourself at home.','A pace that works for you. A little room to make this your own.')}<div class="settings-layout"><section class="settings-card"><h2>Your learning preferences</h2><label class="field-label" for="learner-name">What should we call you?</label><input id="learner-name" maxlength="60" placeholder="Your name" value="${escape(progress.name)}" autocomplete="given-name"><div class="name-preview">${he('קוֹרְאִים לִי')} <bdi>${escape(progress.name||'…')}</bdi><span>ko-RIM li · My name is…</span></div><label class="field-label" for="form-select">Grammar examples</label><select id="form-select"><option value="m" ${progress.form==='m'?'selected':''}>Masculine forms</option><option value="f" ${progress.form==='f'?'selected':''}>Feminine forms</option></select><p class="field-help">Changes speaker forms and the singular person addressed. Each example explains which applies. You can switch anytime.</p><label class="toggle-row"><span><strong>Pronunciation hints</strong><small>Show Latin transliteration under Hebrew</small></span><input id="transliteration" type="checkbox" ${progress.transliteration?'checked':''}></label><label class="toggle-row"><span><strong>Vowel marks</strong><small>Show niqqud while you’re getting started</small></span><input id="vowels" type="checkbox" ${progress.vowels?'checked':''}></label><label class="field-label" for="goal-select">Your daily intention</label><select id="goal-select">${[[20,'Gentle · 20 XP'],[30,'Steady · 30 XP'],[50,'A little extra · 50 XP']].map(([n,t])=>`<option value="${n}" ${progress.goal===n?'selected':''}>${t}</option>`).join('')}</select><button class="button primary" id="save-settings">Save preferences ${icon('check')}</button></section><section><article class="settings-card account-card"><span class="account-avatar">${escape((progress.name||user?.displayName||'G')[0].toUpperCase())}</span><h2>${user?escape(user.displayName||'Your account'):'You’re learning as a guest.'}</h2><p>${user?escape(user.email||'Google account'):'No account needed. Your progress saves in this browser, on this device.'}</p><div class="account-status">${icon('check')}${user?({local:'Saved on this device',pending:'Waiting to sync…',saving:'Saving to your account…',saved:'Synced with your account',error:'Cloud sync paused'})[syncState]:'Saved on this device'}</div>${user?`<button class="button secondary full" id="sync-now">Sync now ${icon('repeat')}</button><button class="text-button" id="sign-out">Sign out</button>`:`<button class="button secondary full" id="google-signin">${icon('google')} Continue with Google</button><small>Bring your guest progress with you and continue across devices.</small>`}</article><article class="settings-card"><h2>Keep your progress close.</h2><p>Guest progress belongs to this browser. Clearing site data removes it. Export a backup to keep a copy.</p><div class="backup-actions"><button class="button secondary" id="export-progress">${icon('download')} Export</button><label class="button secondary import-label">Import<input id="import-progress" type="file" accept="application/json,.json" class="sr-only"></label></div><p class="field-help">Imports merge with your progress. Daily XP uses the larger total per day so a backup cannot duplicate it.</p><button class="text-button danger" id="reset-progress">Reset ${user?'account':'guest'} progress</button></article>${user&&rewardSyncStatus()==='local'?'<p class="info-banner">Lessons sync to your account. New rewards are saved on this device until the site owner updates Firebase rules.</p>':''}<article class="settings-card install-card"><div class="install-heading"><img src="/apple-touch-icon.png?v=6" alt="" width="48" height="48"><div><h2>Binah, on your Home Screen.</h2><p>Open straight into your learning, like an app.</p></div></div><button class="button secondary full" data-install>How to add Binah</button><p class="field-help" data-install-status></p></article><p class="privacy-note">No ads. No analytics. Your learning data is stored locally. Google accounts additionally store progress in a private account record. Browser-provided Hebrew audio may use your device’s speech service.</p></section></div>`;}
function render(){const reconciled=reconcileFreezes(progress);if(reconciled!==progress){progress=reconciled;save();}app.dataset.view=tab;trace?.destroy();trace=null;if(session){renderSession();return;}app.innerHTML=shell(({learn:learning,letters:lettersPage,review:practicePage,library:libraryPage,settings:settingsPage,rewards:rewardsPage}[tab]||learning)());bind();if(tab==='letters'&&letterMode==='letters')mountLetter();enterView(app,'page:'+tab+':'+activeUnit+':'+traceIndex+':'+letterMode);}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$('.brand').onclick=e=>{e.preventDefault();setTab('learn');};document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{activeUnit=Number(b.dataset.unit);render();});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>startLesson(b.dataset.lesson));document.querySelectorAll('[data-letter]').forEach(b=>b.onclick=()=>{traceIndex=Number(b.dataset.letter);render();});document.querySelectorAll('[data-letter-mode]').forEach(b=>b.onclick=()=>{letterMode=b.dataset.letterMode;render();});if($('#unit-select'))$('#unit-select').onchange=e=>{activeUnit=Number(e.target.value);render();};if($('#letter-select'))$('#letter-select').onchange=e=>{traceIndex=Number(e.target.value);render();};bindSpeech();bindInstallUI();if($('#letter-quiz'))$('#letter-quiz').onclick=startLetterQuiz;if($('#start-review'))$('#start-review').onclick=startReview;if($('#start-typing'))$('#start-typing').onclick=()=>startTypingPractice();if($('#choose-typing'))$('#choose-typing').onclick=typingBrowser;if($('#phrase-search'))$('#phrase-search').oninput=e=>{wordQuery=e.target.value;$('#phrase-results').innerHTML=phraseResults(allPhrases.filter(p=>progress.cards[p.id]));bindSpeech();$('#phrase-results').querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));};if(tab==='settings')bindSettings();bindRewards();for(const b of document.querySelectorAll('[data-writing-group]'))b.onclick=()=>launchWritingRound(b.dataset.writingGroup,b.dataset.kind,{getProgress:()=>progress,onProgress:p=>{progress=p;save();},onClose:()=>render(),speak});}
function bindSpeech(){document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(b.dataset.speak));}
function speak(text){if(!('speechSynthesis' in window)){toast('Audio isn’t supported here. Use the pronunciation hint below the Hebrew.');return;}const voices=speechSynthesis.getVoices(),voice=voices.find(v=>/^he(?:-|$)|^iw(?:-|$)/i.test(v.lang));if(!voice){toast('No Hebrew voice found. Add a Hebrew voice in your device’s speech settings.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.voice=voice;utterance.lang='he-IL';utterance.rate=.8;utterance.onerror=()=>toast('Audio could not play. Try again or use the pronunciation hint.');speechSynthesis.speak(utterance);}
function mountLetter(){
 const l=alphabet[traceIndex];
 trace=mountTrace($('#trace-writer'),l,result=>{
  progress=recordLetter(progress,l.char);save();$('.trace-panel').classList.add('is-success');
  $('#trace-next').hidden=false;
  feedbackMotion($('#trace-instruction'),true);celebrateAt($('#trace-writer'));
  if(!progress.traced.includes(l.char)){
   progress.traced.push(l.char);progress=award(progress,5);save();
   const tile=$('.letter-tile.selected');tile?.classList.add('traced');
   if(tile&&!tile.querySelector('.tiny-check'))tile.insertAdjacentHTML('beforeend','<span class="tiny-check" aria-label="Practiced">✓</span>');
   const count=$('.letter-library summary small');if(count)count.textContent=progress.traced.length+' practiced';
   const stats=document.querySelectorAll('.top-stats strong');if(stats[0])stats[0].textContent=streak(progress);if(stats[1])stats[1].textContent=totalXP(progress);
   toast(l.name+' practiced · +5 XP');
  }
 },{onChange(result){
  $('#trace-count').textContent=result.reached+' / '+result.total+' strokes';
  $('#trace-percent').textContent=result.coverage+'%';$('#trace-progress').value=result.coverage;
  $('#trace-instruction').textContent=result.watching?'Watch the strokes, then try it yourself.':result.pass?'All strokes complete.':result.mode==='recall'?'Write from memory. Use Hint whenever you need.':`Stroke ${result.reached+1} of ${result.total} · ${result.instruction}`;
  $('#trace-next').hidden=!result.pass;
  for(const button of document.querySelectorAll('[data-trace-mode]'))button.setAttribute('aria-pressed',button.dataset.traceMode===result.mode);
  $('#trace-watch').disabled=result.watching&&!result.preview;$('#trace-watch').textContent=result.preview?'Back to writing':'Watch';$('#trace-hint').disabled=result.watching||result.pass;
  $('.trace-panel').classList.toggle('is-success',result.pass);
 },onFeedback({text,kind}){
  $('.trace-panel').dataset.feedback='shown';$('#trace-instruction').textContent=text;
  $('#trace-instruction').classList.toggle('success',kind==='complete'||kind==='correct');
  $('#trace-instruction').dataset.kind=kind;
 }});
 $('#trace-clear').onclick=()=>trace.clear();
 $('#trace-hint').onclick=()=>trace.hint();
 $('#trace-watch').onclick=()=>trace.play();
 $('#trace-next').onclick=()=>{traceIndex=(traceIndex+1)%27;render();};
 for(const button of document.querySelectorAll('[data-trace-mode]'))button.onclick=()=>trace.setMode(button.dataset.traceMode);
}

function startLesson(id){const lesson=lessons.find(l=>l.id===id);if(!lesson)return;const available=lesson.index===0||progress.completed[lesson.id]||progress.completed[lessons[lesson.index-1].id];if(!available){toast('Complete the previous lesson to unlock this one.');return;}session={kind:'lesson',lesson,steps:makeSession(lesson,progress.form),index:-1,correct:0,graded:0,attempts:0,answered:false,chosen:null,tokens:[],results:{},finished:false};renderSession();window.scrollTo(0,0);}
function startReview(){const due=dueCards(),pool=due.length?due:allPhrases.filter(p=>progress.cards[p.id]);const phrases=shuffled(pool).slice(0,10).map(p=>variant(p,progress.form));if(!phrases.length)return;session={kind:'review',steps:phrases.map(p=>({type:'choice',phrase:p,answer:p.en,options:shuffled([p.en,...shuffled([...new Set(allPhrases.map(q=>q.en))].filter(x=>x!==p.en)).slice(0,3)])})),index:0,correct:0,graded:0,attempts:0,answered:false,chosen:null,tokens:[],results:{},finished:false};renderSession();window.scrollTo(0,0);}
function startLetterQuiz(){const letters=shuffled(alphabet).slice(0,8);session={kind:'letters',steps:letters.map(l=>({type:'letter',letter:l,answer:l.name,options:shuffled([l.name,...shuffled(alphabet.filter(x=>x.name!==l.name)).slice(0,3).map(x=>x.name)])})),index:0,correct:0,graded:0,attempts:0,answered:false,chosen:null,tokens:[],results:{},finished:false};renderSession();window.scrollTo(0,0);}
function startTypingPractice(pool=allPhrases,randomize=true){const phrases=(randomize?shuffled(pool):pool).slice(0,8).map(p=>variant(p,progress.form));if(!phrases.length)return;const steps=phrases.flatMap((p,i)=>i<3?[{type:'type-demo',phrase:p,answer:p.he},{type:'type',phrase:p,answer:p.he}]:[{type:'type',phrase:p,answer:p.he}]);session={kind:'typing',steps,index:0,correct:0,graded:0,attempts:0,answered:false,chosen:null,tokens:[],typed:'',results:{},finished:false};renderSession();window.scrollTo(0,0);}
function typingBrowser(){const box=$('#typing-browser');if(!box)return;box.hidden=false;updateTypingBrowser();$('#typing-browse-search').oninput=e=>{typingQuery=e.target.value;updateTypingBrowser();};box.querySelectorAll('[data-typing-filter]').forEach(b=>b.onclick=()=>{typingFilter=b.dataset.typingFilter;updateTypingBrowser();});$('#close-typing-browser').onclick=()=>{box.hidden=true;};$('#start-selected-typing').onclick=()=>{const chosen=allPhrases.filter(p=>typingSelected.has(p.id));if(chosen.length)startTypingPractice(chosen,false);};}
function updateTypingBrowser(){const grid=$('#typing-choice-grid');if(!grid)return;const q=normalize(typingQuery),filtered=allPhrases.filter(p=>{const word=p.en.trim().split(/\\s+/).length===1;const type=word?'words':'phrases';return(typingFilter==='all'||typingFilter===type)&&[p.he,p.en,p.roman,p.f?.he||''].some(v=>normalize(v).includes(q));});grid.innerHTML=filtered.map(p=>{const chosen=typingSelected.has(p.id),disabled=!chosen&&typingSelected.size>=8;const v=variant(p,progress.form);return `<div class="typing-choice ${chosen?'selected':''}"><label class="typing-choice-select"><input type="checkbox" data-typing-select="${escape(p.id)}" ${chosen?'checked':''} ${disabled?'disabled':''}><span class="typing-choice-copy"><strong lang="he" dir="rtl">${escape(progress.vowels?v.he:(v.unpointed||v.he))}</strong><small>${escape(v.en)}</small><em>${escape(v.roman)}</em></span></label><button type="button" class="icon-button" data-speak="${escape(v.he)}" aria-label="Hear ${escape(v.en)}">${icon('sound')}</button></div>`;}).join('')||'<div class="empty-state"><h3>No matches found.</h3><p>Try another word or switch the filter.</p></div>';grid.querySelectorAll('[data-typing-select]').forEach(input=>input.onchange=()=>{if(input.checked)typingSelected.add(input.dataset.typingSelect);else typingSelected.delete(input.dataset.typingSelect);updateTypingBrowser();});$('#typing-selection-count').textContent=typingSelected.size+' of 8 selected';$('#start-selected-typing').disabled=typingSelected.size===0;boxFilterButtons();bindSpeech();}
function boxFilterButtons(){document.querySelectorAll('[data-typing-filter]').forEach(b=>b.classList.toggle('active',b.dataset.typingFilter===typingFilter));}
function renderSession(){app.dataset.view='lesson';trace?.destroy();trace=null;const s=session;if(!s)return;if(s.finished){renderComplete();return;}const step=s.steps[s.index],intro=s.index===-1,learn=step?.type==='learn'||step?.type==='type-demo',fraction=Math.max(0,s.index)/s.steps.length;app.innerHTML=`<div class="lesson-shell" data-step="${intro?'intro':step.type}"><header class="lesson-header"><button id="exit-lesson" class="icon-button" aria-label="Leave lesson">${icon('close')}</button><progress value="${fraction}" max="1" aria-label="Lesson progress"></progress><span>${intro?'LET’S BEGIN':Math.min(s.index+1,s.steps.length)+' / '+s.steps.length}</span></header><main id="main" class="exercise-main" tabindex="-1">${intro?`<div class="lesson-intro"><span class="intro-icon">${icon(units.find(u=>u.id===s.lesson.unit).icon)}</span><p class="eyebrow">A LITTLE CONTEXT FIRST</p><h1>${s.lesson.title}</h1><p>${s.lesson.tip}</p><div class="outcome"><span class="eyebrow">BY THE END, YOU CAN…</span><p>${s.lesson.scenario}</p></div>${s.lesson.id==='name'?`<label class="field-label" for="intro-name">Your name (keep the spelling you use)</label><input id="intro-name" maxlength="60" value="${escape(progress.name)}" placeholder="Your name"><div class="name-preview">${he('קוֹרְאִים לִי')} <bdi id="live-name">${escape(progress.name||'…')}</bdi></div>`:''}</div>`:exerciseBody(step,s)}</main><div class="exercise-bottom ${s.answered?(s.wasCorrect?'correct':'incorrect'):''}"><div class="feedback" role="status">${s.answered?(s.wasCorrect?`${icon('check')}<div><strong>That’s it!</strong><span>${step.phrase?escape(step.phrase.en):'You’re getting to know your alef-bet.'}</span></div>`:`${icon('heart')}<div><strong>A useful one to remember.</strong><span>${escape(step.answer)}${step.phrase?' · '+escape(step.phrase.roman):''}</span></div>`):`<span>${intro?'Useful Hebrew, from the very beginning.':learn?'Say it out loud, if you can.':'Take your time. Mistakes are part of learning.'}</span>`}</div><button class="button primary" id="exercise-next" ${!intro&&!learn&&!s.answered&&!canCheck(s)?'disabled':''}>${intro?'Let’s try it':step?.type==='type-demo'?'I’m ready to try':learn?'Got it':s.answered?'Continue':'Check answer'} ${icon('arrow')}</button></div></div>`;
$('#exit-lesson').onclick=()=>{if(confirm('Leave this practice? This attempt will restart.')){session=null;render();}};$('#exercise-next').onclick=nextStep;
if($('#intro-name'))$('#intro-name').oninput=e=>{$('#live-name').textContent=e.target.value||'…';};
document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{if(s.answered)return;s.chosen=b.dataset.option;renderSession();});
document.querySelectorAll('[data-token]').forEach(b=>b.onclick=()=>{if(s.answered)return;s.tokens.push(Number(b.dataset.token));renderSession();});
document.querySelectorAll('[data-remove-token]').forEach(b=>b.onclick=()=>{if(s.answered)return;s.tokens.splice(Number(b.dataset.removeToken),1);renderSession();});
if($('#type-answer')){$('#type-answer').value=s.typed||'';$('#type-answer').oninput=e=>{s.typed=e.target.value;$('#exercise-next').disabled=!canCheck(s);};$('#type-answer').onkeydown=e=>{if(e.key==='Enter'&&canCheck(s)&&!s.answered)nextStep();};}
document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{if(s.answered)return;const input=$('#type-answer'),start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.value=input.value.slice(0,start)+b.dataset.key+input.value.slice(end);s.typed=input.value;if(!matchMedia('(pointer: coarse)').matches)input.focus({preventScroll:true});input.setSelectionRange(start+1,start+1);$('#exercise-next').disabled=!canCheck(s);});
bindSpeech();enterView(app,'exercise:'+s.kind+':'+(s.lesson?.id||'')+':'+s.index);if(s.answered)feedbackMotion($('.exercise-bottom'),s.wasCorrect);}
function canCheck(s){const step=s.steps[s.index];return step?.type==='build'?s.tokens.length>0:step?.type==='type'?!!s.typed?.trim():s.chosen!==null;}
function exerciseBody(step,s){const p=step.phrase;let title=({learn:'A phrase you’ll actually use.',choice:'What does this mean?',scenario:'What would you say?',build:'Build the Hebrew phrase.',type:'Your turn to write.','type-demo':'Here’s how to write it.',letter:'What is this letter called?'})[step.type];return `<p class="eyebrow">${step.type==='learn'?'MEET YOUR NEW PHRASE':step.type==='type-demo'?'GUIDED EXAMPLE':step.type==='scenario'?'A REAL-LIFE MOMENT':'A LITTLE PRACTICE'}</p><h1>${title}</h1>${step.type==='scenario'?`<p class="scenario-prompt">${escape(step.prompt)}</p>`:''}${step.type==='letter'?`<div class="quiz-letter" lang="he">${step.letter.char}</div>`:step.type==='build'||step.type==='type'?`<p class="translate-prompt">${escape(p.en)}</p>`:step.type==='scenario'?'':`<article class="teaching-card"><button class="icon-button" data-speak="${escape(p.he)}" aria-label="Hear phrase">${icon('sound')}</button><p class="large-hebrew">${hePhrase(p)}</p>${step.type==='learn'||step.type==='type-demo'?roman(p):''}${step.type==='learn'||step.type==='type-demo'?`<h2>${escape(p.en)}</h2>${p.id==='korim'&&progress.name?`<p class="own-name" dir="rtl" lang="he">${hePhrase(p)} <bdi>${escape(progress.name)}</bdi></p>`:''}<p class="phrase-note">${escape(step.type==='type-demo'?'Read the Hebrew from right to left, listen to the pronunciation, then try typing it from memory.':p.note||'Learn the sound with the meaning. You’ll use this in a moment.')}</p>`:''}</article>`}${['choice','letter','scenario'].includes(step.type)?`<div class="choice-list">${step.options.map((o,i)=>`<button data-option="${escape(o)}" class="choice ${s.chosen===o?'selected':''} ${s.answered&&o===step.answer?'answer-correct':''} ${s.answered&&s.chosen===o&&!s.wasCorrect?'answer-wrong':''}" ${s.answered?'disabled':''}><span class="choice-number">${i+1}</span><span ${step.type==='scenario'?'lang="he" dir="rtl" class="option-he"':''}>${escape(step.type==='scenario'&&!progress.vowels?bareSpell(o):o)}</span></button>`).join('')}</div>`:''}${step.type==='build'?`<div class="token-answer" dir="rtl" aria-label="Your sentence">${s.tokens.map((n,i)=>`<button data-remove-token="${i}" class="word-token" lang="he" ${s.answered?'disabled':''}>${escape(displayWord(step.tokens[n],step.phrase))}</button>`).join('')||'<span class="muted">Tap the words below</span>'}</div><div class="word-bank" dir="rtl">${step.tokens.map((w,i)=>`<button class="word-token ${s.tokens.includes(i)?'used':''}" data-token="${i}" lang="he" ${s.tokens.includes(i)||s.answered?'disabled':''}>${escape(displayWord(w,step.phrase))}</button>`).join('')}</div>`:''}${step.type==='type'?`<label class="sr-only" for="type-answer">Type the Hebrew for ${escape(p.en)}</label><input id="type-answer" class="hebrew-input" dir="rtl" lang="he" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="כתבו כאן…" ${s.answered?'disabled':''}><p class="field-help">Vowel marks and punctuation are optional. Use your keyboard or the letters below.</p><div class="hebrew-keyboard" dir="rtl" aria-label="Hebrew letter keyboard">${'אבגדהוזחטיכךלמםנןסעפףצץקרשת'.split('').map(c=>`<button data-key="${c}" lang="he" aria-label="Insert ${c}" ${s.answered?'disabled':''}>${c}</button>`).join('')}<button class="space-key" data-key=" " ${s.answered?'disabled':''}>Space</button></div>`:''}`;}
function nextStep(){const s=session,step=s.steps[s.index];if(s.index===-1){if($('#intro-name')){progress.name=$('#intro-name').value.trim();save();}advance();return;}if(step.type==='learn'||step.type==='type-demo'||s.answered){advance();return;}if(!canCheck(s))return;
let value=step.type==='build'?s.tokens.map(i=>step.tokens[i]).join(' '):step.type==='type'?s.typed:s.chosen;
s.wasCorrect=answerMatches(step,value,step.phrase?.unpointed||bareSpell(step.answer));s.answered=true;s.graded++;s.attempts++;if(s.wasCorrect)s.correct++;if(step.phrase)s.results[step.phrase.id]=s.wasCorrect;renderSession();$('#exercise-next').focus();}
function advance(){const s=session;s.index++;s.answered=false;s.chosen=null;s.tokens=[];s.typed='';if(s.index>=s.steps.length){s.finished=true;finishSession();renderComplete();}else{renderSession();$('#main').focus();}window.scrollTo(0,0);}
function finishSession(){const s=session;s.levelBefore=levelState(progress).level;const sparksBefore=sparkBalance(progress);const success=s.graded>0&&s.correct/s.graded>=.7;s.passed=success;const xp=success?(s.kind==='lesson'?(progress.completed[s.lesson.id]?10:30):s.kind==='letters'?10:15):5;s.xp=xp;
if(s.kind==='lesson'&&success){progress.completed[s.lesson.id]=Date.now();progress=recordLesson(progress,s.lesson.id);}for(const [id,correct] of Object.entries(s.results))progress=scheduleCard(progress,id,correct);progress=award(progress,xp);s.sparksEarned=sparkBalance(progress)-sparksBefore;save();}
function renderComplete(){app.dataset.view='complete';const s=session;app.innerHTML=`<main id="main" class="complete-screen"><div class="complete-mark">${icon(s.passed?'spark':'heart')}</div><p class="eyebrow">${s.passed?'ONE STEP CLOSER':'EVERY TRY IS PRACTICE'}</p><h1>${s.passed?'Look at you,<br>learning Hebrew.':'Let’s give it<br>another go.'}</h1><p>${s.passed?(s.kind==='lesson'?'Another little piece of the language is yours.':s.kind==='typing'?'You translated Hebrew phrases without needing a lesson.':'Those familiar words are getting a little stronger.'):'Reach 70% to complete this '+(s.kind==='typing'?'practice round':'lesson')+'. Your practice still counts, and you can try again anytime.'}</p><div class="completion-level"><span>Level ${levelState(progress).level}${levelState(progress).level>s.levelBefore?' · Level up!':''}</span><progress value="${levelState(progress).percent}" max="100" aria-label="Level progress"></progress><small>${s.sparksEarned?'+'+s.sparksEarned+' sparks · ':''}${levelState(progress).next-levelState(progress).xp} XP to the next level</small></div><div class="completion-stats"><div><strong>+${s.xp}</strong><span>XP EARNED</span></div><div><strong>${Math.round(s.correct/s.graded*100)}%</strong><span>ACCURACY</span></div><div><strong>${streak(progress)}</strong><span>DAY STREAK</span></div></div><button class="button primary" id="finish-back">${s.passed?'Back to your journey':'Try again'} ${icon('arrow')}</button><button class="text-button" id="finish-done">${s.passed?'Take a little break':'Back to your path'}</button></main>`;$('#finish-back').onclick=()=>{const previous=session;session=null;if(!previous.passed){if(previous.kind==='lesson')startLesson(previous.lesson.id);else if(previous.kind==='letters')startLetterQuiz();else if(previous.kind==='typing')startTypingPractice();else startReview();}else{if(previous.kind==='lesson')activeUnit=units.findIndex(u=>u.id===nextLesson(lessons,progress).unit);render();}};$('#finish-done').onclick=()=>{session=null;render();};enterView(app,'complete:'+s.kind+':'+(s.lesson?.id||'')+':'+s.passed);if(s.passed)celebrateAt($('.complete-mark'),{big:true});}
function bindSettings(){
$('#save-settings').onclick=()=>{progress.name=$('#learner-name').value.trim();progress.form=$('#form-select').value;progress.transliteration=$('#transliteration').checked;progress.vowels=$('#vowels').checked;progress.goal=Number($('#goal-select').value);save();render();toast('Your space, a little more you.');};
$('#learner-name').oninput=e=>{const preview=$('.name-preview');preview.innerHTML=he('קוֹרְאִים לִי')+' <bdi>'+escape(e.target.value||'…')+'</bdi><span>ko-RIM li · My name is…</span>';};
if($('#google-signin'))$('#google-signin').onclick=async()=>{if(!authReady){toast(cloudConfigured()?'Sign-in is still connecting. Please try again in a moment.':'Google sign-in isn’t available here yet. Your guest progress is saved on this device.');return;}pendingGuest=structuredClone(progress);try{await signInGoogle();}catch(e){pendingGuest=null;toast(e.code==='auth/popup-closed-by-user'?'Sign-in closed. You can keep learning as a guest.':'Could not sign in. Check your connection and try again.');}};
if($('#sign-out'))$('#sign-out').onclick=async()=>{try{clearTimeout(syncTimer);await writeCloud(user.uid,progress);await signOutGoogle();}catch{toast('Could not finish syncing. Try again before signing out.');}};
if($('#sync-now'))$('#sync-now').onclick=()=>sync(user.uid);
$('#export-progress').onclick=()=>{const blob=new Blob([JSON.stringify(progress,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='binah-progress-'+dayKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);};
$('#import-progress').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>1000000){toast('That backup is too large. Choose a Binah progress file under 1 MB.');return;}try{const raw=JSON.parse(await file.text());if(raw.version!==1||!raw.completed||!raw.cards||!raw.activity)throw Error();progress=mergeProgress(progress,sanitize(raw));save();render();toast('Your progress is back where it belongs.');}catch{toast('That file is not a valid Binah progress backup.');}};
$('#reset-progress').onclick=async()=>{if(!confirm(`Reset all ${user?'account':'guest'} progress? This clears completed lessons, reviews, and XP${user?' on this account and this device':''}. Export a backup first if you want to keep a copy.`))return;try{clearTimeout(syncTimer);if(user)await deleteCloud(user.uid);progress=emptyProgress();save({cloud:false});render();toast('A fresh start. Your journey is ready.');}catch{toast('Could not reset your account. Try again when you are online.');}};
}
window.addEventListener('hashchange',()=>{const t=location.hash.slice(1);if(['learn','letters','review','library','settings','rewards'].includes(t)&&t!==tab){if(session){location.hash=tab;return;}tab=t;render();}});
window.addEventListener('online',()=>{if(user)sync(user.uid);});
window.addEventListener('storage',e=>{if(e.key===key&&e.newValue){try{progress=mergeProgress(progress,JSON.parse(e.newValue));if(!session)render();}catch{}}});
window.addEventListener('beforeunload',e=>{if(session&&!session.finished){e.preventDefault();e.returnValue='';}});
if(['learn','letters','review','library','settings','rewards'].includes(location.hash.slice(1)))tab=location.hash.slice(1);
render();
if(cloudConfigured())initCloud(async account=>{clearTimeout(syncTimer);const previous=user;user=account;key=account?'binah:user:'+account.uid:'binah:guest';if(!account){progress=load(key);syncState='local';if(previous){session=null;render();}return;}
const uid=account.uid,guest=pendingGuest;pendingGuest=null;progress=load(key);if(guest)progress=mergeProgress(progress,guest);save({cloud:false});if(!session)render();
try{const remote=await readCloud(uid);if(user?.uid!==uid)return;if(remote)progress=mergeProgress(progress,remote);save({cloud:false});syncState='saved';if(guest)await sync(uid);if(!session)render();}catch{syncState='error';toast('Cloud progress could not load. You can keep learning on this device.');if(!session)render();}
}).then(ready=>authReady=ready).catch(()=>toast('Account services could not connect. Guest learning is still available.'));
if('speechSynthesis' in window)speechSynthesis.getVoices();
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});

function rewardsPage(){
 const level=levelState(progress),stock=freezeStock(progress),sparks=sparkBalance(progress),quests=dailyQuests(progress);
 const week=Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-6+i);const day=dayKey(date),practiced=!!progress.activity[day],frozen=Object.hasOwn(progress.game.freezes,day);return `<div class="week-day ${practiced?'practiced':frozen?'frozen':''}"><span>${date.toLocaleDateString(undefined,{weekday:'short'})}</span><strong>${practiced?'✓':frozen?'❄':date.getDate()}</strong><small>${practiced?'Practiced':frozen?'Protected':i===6?'Today':'Rest day'}</small></div>`;}).join('');
 return `${heading('YOUR MOMENTUM','A little progress adds up.','Build a habit, celebrate what you know, and make room for a day off.')}<div class="rewards-overview"><article class="reward-level"><img src="/brand-mark.svg" alt="" width="54" height="54"><div><span class="eyebrow">YOUR GROWING UNDERSTANDING</span><h2>Level ${level.level}</h2><progress value="${level.percent}" max="100" aria-label="Level progress"></progress><p>${level.next-level.xp} XP to the next level</p></div></article><article class="reward-balance"><span class="eyebrow">SPARKS</span><strong>${sparks}</strong><p>Earned through learning.</p></article></div><div class="rewards-grid"><section class="reward-card streak-card"><div class="reward-card-title"><h2>${streak(progress)} day streak</h2><span class="reward-symbol" aria-hidden="true">${icon('flame')}</span></div><div class="week-strip">${week}</div><div class="freeze-summary"><span class="freeze-symbol" aria-hidden="true">❄</span><div><strong>${stock} / ${FREEZE_CAP} freezes equipped</strong><p>One comes free. A freeze automatically protects a missed day without adding XP.</p></div></div><button class="button secondary full" id="buy-freeze" ${stock>=FREEZE_CAP||sparks<FREEZE_COST?'disabled':''}>${stock>=FREEZE_CAP?'Fully equipped':'Equip a freeze · '+FREEZE_COST+' sparks'}</button><p id="freeze-feedback" class="field-help" role="status">${stock>=FREEZE_CAP?'You’re ready for a couple of days off.':sparks<FREEZE_COST?`${FREEZE_COST-sparks} more sparks for another freeze.`:'Your next day off can be covered.'}</p></section><section class="reward-card"><div class="reward-card-title"><h2>Today’s quests</h2><span class="muted">${quests.filter(q=>q.claimed).length} / 3 claimed</span></div>${quests.map(q=>`<article class="daily-quest"><div><strong>${q.title}</strong><span>${q.value} / ${q.target} ${q.id==='intention'?'XP':q.id==='letters'?'letters':'lesson'}</span><progress value="${q.value}" max="${q.target}" aria-label="${q.title}"></progress></div><button class="button ${q.complete&&!q.claimed?'primary':'secondary'}" data-claim-quest="${q.id}" ${!q.complete||q.claimed?'disabled':''}>${q.claimed?'Claimed':q.complete?'+10 sparks':'In progress'}</button></article>`).join('')}<details class="reward-explainer"><summary>How do I earn sparks?</summary><p>15 for each new conversation lesson, 3 for each new letter practiced, 5 for each writing-test star, and 10 for each daily quest you claim. No purchases or ads.</p></details></section></div><section class="achievements"><div class="path-title"><h2>Little milestones</h2><span class="muted">${achievements(progress).filter(a=>a.earned).length} / 6</span></div><div class="achievement-grid">${achievements(progress).map(a=>`<article class="achievement ${a.earned?'earned':''}"><span class="achievement-mark" aria-hidden="true">${icon(a.earned?'spark':'lock')}</span><div><h3>${a.title}</h3><p>${a.detail}</p><small>${a.earned?'Earned':'Keep learning'}</small></div></article>`).join('')}</div></section>`;
}
function bindRewards(){
 if($('#buy-freeze'))$('#buy-freeze').onclick=()=>{const result=buyFreeze(progress);progress=result.progress;if(result.ok){save();render();toast('Streak freeze equipped. A little breathing room.');}else $('#freeze-feedback').textContent=result.reason;};
 for(const b of document.querySelectorAll('[data-claim-quest]'))b.onclick=()=>{const next=claimQuest(progress,b.dataset.claimQuest);if(next!==progress){progress=next;save();render();toast('Quest complete · +10 sparks');}};
}
